class Solution {
    public int countCalm(int[] noise, int k, int limit) {
        int count = 0;
        for (int i = 0; i + k <= noise.length; i++) {
            long total = 0;
            for (int j = i; j < i + k; j++) total += noise[j];
            if (total <= (long) limit * k) count++;
        }
        return count;
    }
}

