class Solution:
    def countCalm(self, noise: List[int], k: int, limit: int) -> int:
        cap = limit * k
        total = sum(noise[:k])
        count = 1 if total <= cap else 0
        for i in range(k, len(noise)):
            total += noise[i] - noise[i - k]
            if total <= cap:
                count += 1
        return count

