        long cap = (long) limit * k, total = 0;
        for (int i = 0; i < k; i++) total += noise[i];
        int count = total <= cap ? 1 : 0;
        for (int i = k; i < noise.length; i++) {
            total += noise[i] - noise[i - k];
            if (total <= cap) count++;
        }
        return count;
    }
}

